const validationErrors = [];
const storageIsObject = $json.storage !== null
  && typeof $json.storage === 'object'
  && !Array.isArray($json.storage);
const storage = storageIsObject ? $json.storage : {};
const operations = Array.isArray(storage.pending_operations) ? storage.pending_operations : [];
const supportedOperations = new Set([
  'create_root_folder',
  'create_directory',
  'create_markdown',
  'create_json',
  'write',
  'create_file',
]);

if ($json.schema_version !== '1.0') validationErrors.push('Invalid schema_version: expected 1.0.');
if ($json.workflow_version !== '1.0') validationErrors.push('Invalid workflow_version: expected 1.0.');
if ($json.route !== 'storage.intake.created') validationErrors.push('Invalid route: expected storage.intake.created.');
if ($json.status !== 'ready') validationErrors.push('Invalid status: expected ready.');
if ($json.is_valid !== true) validationErrors.push('Invalid upstream contract: is_valid must be true.');
if (!storageIsObject) validationErrors.push('Invalid storage: expected an object.');
if (typeof storage.chapter_uuid !== 'string' || !storage.chapter_uuid.trim()) validationErrors.push('storage.chapter_uuid is required.');
if (typeof storage.workspace_uuid !== 'string' || !storage.workspace_uuid.trim()) validationErrors.push('storage.workspace_uuid is required.');
if (typeof storage.novel_uuid !== 'string' || !storage.novel_uuid.trim()) validationErrors.push('storage.novel_uuid is required.');
if (storage.storage_provider !== 'google_drive') validationErrors.push('storage.storage_provider must equal google_drive.');
if (typeof storage.storage_strategy !== 'string' || !storage.storage_strategy.trim()) validationErrors.push('storage.storage_strategy is required.');
if (!Array.isArray(storage.pending_operations)) {
  validationErrors.push('storage.pending_operations must be an array.');
}

operations.forEach((operation, index) => {
  if (!operation || typeof operation !== 'object' || Array.isArray(operation)) {
    validationErrors.push(`storage.pending_operations[${index}] must be an object.`);
    return;
  }
  const operationName = typeof operation.operation === 'string' ? operation.operation.trim().toLowerCase() : '';
  const path = typeof operation.path === 'string'
    ? operation.path.trim().replace(/\\/g, '/').replace(/^\/+|\/+$/g, '').replace(/\/{2,}/g, '/')
    : '';
  if (!supportedOperations.has(operationName)) {
    validationErrors.push(`storage.pending_operations[${index}].operation is unsupported.`);
  }
  if (operationName !== 'create_root_folder' && !path) {
    validationErrors.push(`storage.pending_operations[${index}].path is required.`);
  }
  if (path.split('/').includes('..')) {
    validationErrors.push(`storage.pending_operations[${index}].path must not traverse parent directories.`);
  }
  if ((operationName === 'write' || operationName === 'create_file') && path && !/\.(md|json)$/iu.test(path)) {
    validationErrors.push(`storage.pending_operations[${index}] file extension must be .md or .json.`);
  }
});

return [{
  json: {
    ...$json,
    status: validationErrors.length === 0 ? 'ready' : 'error',
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors,
  },
}];

const storage = $json.storage !== null
  && typeof $json.storage === 'object'
  && !Array.isArray($json.storage)
  ? $json.storage
  : {};

return [{
  json: {
    is_valid: $json.is_valid === true,
    validation_errors: Array.isArray($json.validation_errors) ? $json.validation_errors : [],
    chapter_uuid: storage.chapter_uuid ?? '',
    workspace_uuid: storage.workspace_uuid ?? '',
    novel_uuid: storage.novel_uuid ?? '',
    storage_provider: storage.storage_provider ?? '',
    storage_strategy: storage.storage_strategy ?? '',
    pending_operations: Array.isArray(storage.pending_operations) ? storage.pending_operations : [],
  },
}];

if ($json.is_valid !== true) {
  return [{ json: { ...$json, generated_operations: [] } }];
}

const rootFolder = $json.workspace_uuid.trim();
const generatedOperations = [{
  operation: 'create_root_folder',
  relative_path: rootFolder,
  source_index: null,
}];

for (const [sourceIndex, source] of $json.pending_operations.entries()) {
  const sourceOperation = source.operation.trim().toLowerCase();
  if (sourceOperation === 'create_root_folder') continue;

  const relativePath = source.path
    .trim()
    .replace(/\\/g, '/')
    .replace(/^\/+|\/+$/g, '')
    .replace(/\/{2,}/g, '/');
  let operation = sourceOperation;
  if (sourceOperation === 'write' || sourceOperation === 'create_file') {
    operation = relativePath.toLowerCase().endsWith('.md') ? 'create_markdown' : 'create_json';
  }

  generatedOperations.push({
    operation,
    relative_path: relativePath,
    source_index: sourceIndex,
  });
}

return [{
  json: {
    ...$json,
    root_folder: rootFolder,
    generated_operations: generatedOperations,
  },
}];

if ($json.is_valid !== true) {
  return [{ json: { ...$json, drive_plan: null } }];
}

const operations = $json.generated_operations.map((operation, index) => ({
  sequence: index + 1,
  operation: operation.operation,
  relative_path: operation.relative_path,
  source_index: operation.source_index,
}));

return [{
  json: {
    ...$json,
    drive_plan: {
      provider: 'google_drive',
      root_folder: $json.root_folder,
      operations,
    },
  },
}];

const isValid = $json.is_valid === true;

return [{
  json: {
    schema_version: '1.0',
    workflow_version: '1.0',
    route: 'storage.drive.plan.created',
    target: 'WF-005-P03',
    status: isValid ? 'ready' : 'error',
    is_valid: isValid,
    validation_errors: $json.validation_errors ?? [],
    drive_plan: isValid ? $json.drive_plan : null,
  },
}];
